import z3
import time

n = 19
vertices = list(range(n))

# Edge variables: e_{i,j} for i < j
e = {}
for i in range(n):
    for j in range(i+1, n):
        e[(i,j)] = z3.Bool(f"e_{i}_{j}")

solver = z3.Solver()

# At least 37 edges
solver.add(z3.Sum([z3.If(e[(i,j)], 1, 0) for (i,j) in e]) >= 37)

# 3-colorability: assign each vertex a color in {0,1,2}
c = [z3.Int(f"c_{i}") for i in range(n)]
for i in range(n):
    solver.add(c[i] >= 0, c[i] <= 2)
for (i,j) in e:
    solver.add(z3.Implies(e[(i,j)], c[i] != c[j]))

print("Starting search...")
start = time.time()

iteration = 0
while True:
    result = solver.check()
    if result == z3.unsat:
        print("UNSAT")
        break
    if result == z3.sat:
        model = solver.model()
        edges_found = []
        for (i,j) in e:
            # Use is_true on the model's evaluation
            val = model.evaluate(e[(i,j)])
            if str(val) == 'true':
                edges_found.append((i,j))
        print(f"Iteration {iteration}: found {len(edges_found)} edges")

        # Build adjacency list
        adj = [[] for _ in range(n)]
        for u,v in edges_found:
            adj[u].append(v)
            adj[v].append(u)

        # Find short cycles using DFS
        def find_short_cycle(max_len):
            for start in range(n):
                stack = [(start, [start])]
                while stack:
                    v, path = stack.pop()
                    if len(path) > max_len:
                        continue
                    for nb in adj[v]:
                        if nb == start and len(path) >= 3 and len(path) <= max_len:
                            cycle_vertices = path
                            cycle_edges = []
                            for k in range(len(cycle_vertices)):
                                u1 = cycle_vertices[k]
                                u2 = cycle_vertices[(k+1) % len(cycle_vertices)]
                                edge = (min(u1, u2), max(u1, u2))
                                cycle_edges.append(edge)
                            return cycle_edges
                        if nb not in path and len(path) < max_len:
                            stack.append((nb, path + [nb]))
            return None

        # Check cycles of length 3 to 7
        cycle_edges = None
        for cl in range(3, 8):
            cycle_edges = find_short_cycle(cl)
            if cycle_edges:
                print(f"Found cycle of length {cl}: {cycle_edges}")
                break

        if cycle_edges is None:
            print("No short cycles found! SATISFIABLE")
            print(f"Edges: {len(edges_found)}")
            print(f"Edges list: {sorted(edges_found)}")
            break
        else:
            # Add constraint: not all these edges present
            solver.add(z3.Not(z3.And([e[edge] for edge in cycle_edges])))
            iteration += 1
    else:
        print("Unknown")
        break

    if time.time() - start > 120:
        print("Timeout")
        break

print(f"Total time: {time.time() - start:.2f}s")

